import React, { useState } from 'react';

// Mock data for existing requirements
const existingRequirements = [
  { id: 'REQ-001', position: 'Assistant Professor, CS', department: 'Computer Science', date: '2025-10-15', status: 'Approved' },
  { id: 'REQ-002', position: 'Lab Technician, Physics', department: 'Physics', date: '2025-10-18', status: 'Pending' },
  { id: 'REQ-003', position: 'Admissions Counselor', department: 'Admissions Office', date: '2025-10-20', status: 'Rejected' },
  { id: 'REQ-004', position: 'Junior Librarian', department: 'Library', date: '2025-10-21', status: 'Pending' },
];

const RequirementPage = () => {
  // NEW: State to control the visibility of the modal form
  const [isModalOpen, setIsModalOpen] = useState(false);

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'Approved': return 'bg-green-100 text-green-800';
      case 'Pending': return 'bg-yellow-100 text-yellow-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="p-8">
      {/* Page Header */}
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Hiring Requirements</h1>
          <p className="text-sm text-subtext-light">Track and manage all open position requests.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600"
        >
          <span className="material-icons mr-2 text-base">add</span> Raise Requirement
        </button>
      </div>

      {/* Main Table of existing requirements */}
      <div className="bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm overflow-x-auto">
         <table className="w-full text-sm text-left">
          <thead className="text-xs text-subtext-light dark:text-subtext-dark uppercase bg-background-light dark:bg-background-dark">
            <tr>
              <th className="px-6 py-3">Request ID</th>
              <th className="px-6 py-3">Position</th>
              <th className="px-6 py-3">Department</th>
              <th className="px-6 py-3">Date Submitted</th>
              <th className="px-6 py-3">Status</th>
              <th className="px-6 py-3 text-center">Action</th>
            </tr>
          </thead>
          <tbody>
            {existingRequirements.map((req) => (
              <tr key={req.id} className="border-b border-border-light dark:border-border-dark hover:bg-gray-50 dark:hover:bg-gray-800/50">
                <td className="px-6 py-4 font-medium">{req.id}</td>
                <td className="px-6 py-4 text-text-light dark:text-white">{req.position}</td>
                <td className="px-6 py-4">{req.department}</td>
                <td className="px-6 py-4">{req.date}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(req.status)}`}>
                    {req.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-center">
                    <button className="text-primary hover:underline text-xs font-medium">View Details</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* NEW: The Modal Form Component */}
      {/* This will only be rendered when isModalOpen is true */}
      {isModalOpen && <RequirementModal closeModal={() => setIsModalOpen(false)} />}
    </div>
  );
};


// --- NEW MODAL COMPONENT ---
const RequirementModal = ({ closeModal }) => {
    const [formData, setFormData] = useState({
        position: '', department: '', positionsCount: 1, justification: ''
    });

    const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

    const handleSubmit = (e) => {
        e.preventDefault();
        console.log("Submitting Requirement:", formData);
        alert("New requirement submitted! (Simulation)");
        closeModal(); // Close the modal on successful submission
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50">
            <div className="bg-card-light dark:bg-card-dark rounded-lg shadow-xl w-full max-w-lg">
                <form onSubmit={handleSubmit}>
                    <div className="p-6 border-b border-border-light">
                        <h3 className="text-xl font-semibold text-text-light dark:text-text-dark">New Position Request</h3>
                    </div>
                    <div className="p-6 space-y-4">
                        <div>
                            <label htmlFor="position" className="block text-sm font-medium text-subtext-light">Position / Title</label>
                            <input type="text" id="position" name="position" value={formData.position} onChange={handleChange} required className="mt-1 w-full" placeholder="e.g., Assistant Professor" />
                        </div>
                        <div>
                            <label htmlFor="department" className="block text-sm font-medium text-subtext-light">Department / Faculty</label>
                            <select id="department" name="department" value={formData.department} onChange={handleChange} required className="mt-1 w-full">
                                <option value="">-- Select Department --</option>
                                <option>Faculty of Engineering</option>
                                <option>Faculty of Arts & Commerce</option>
                                <option>Administration</option>
                            </select>
                        </div>
                        <div>
                            <label htmlFor="positionsCount" className="block text-sm font-medium text-subtext-light">Number of Positions</label>
                            <input type="number" id="positionsCount" name="positionsCount" value={formData.positionsCount} onChange={handleChange} required className="mt-1 w-full" />
                        </div>
                        <div>
                            <label htmlFor="justification" className="block text-sm font-medium text-subtext-light">Justification</label>
                            <textarea id="justification" name="justification" rows="4" value={formData.justification} onChange={handleChange} required className="mt-1 w-full" placeholder="Briefly explain why this position is needed..."></textarea>
                        </div>
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800/50 flex justify-end gap-4 rounded-b-lg">
                        <button type="button" onClick={closeModal} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-300 text-sm">Cancel</button>
                        <button type="submit" className="bg-primary text-white px-4 py-2 rounded-lg hover:bg-blue-600 text-sm">Submit Request</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default RequirementPage;
